{"content":""""Search space definitions for hyperparameter tuning."""

from typing import Any, Dict, List, Optional, Tuple, Union
import numpy as np
from dataclasses import dataclass, field
from abc import ABC, abstractmethod


@dataclass
class ParameterDistribution(ABC):
    """Base class for parameter distributions."""
    name: str

    @abstractmethod
    def sample(self, rng: Optional[np.random.RandomState] = None) -> Any:
        """Sample a value from this distribution."""
        pass

    @abstractmethod
    def to_optuna(self, trial) -> Any:
        """Convert to optuna suggest call."""
        pass

    @abstractmethod
    def to_ray(self) -> Any:
        """Convert to Ray Tune search space."""
        pass


@dataclass
class Uniform(ParameterDistribution):
    """Uniform distribution."""
    low: float
    high: float
    log_scale: bool = False

    def sample(self, rng: Optional[np.random.RandomState] = None) -> float:
        """Sample from uniform distribution."""
        if rng is None:
            rng = np.random.default_rng()

        if self.log_scale:
            log_low, log_high = np.log(self.low), np.log(self.high)
            return float(np.exp(rng.uniform(log_low, log_high)))
        return float(rng.uniform(self.low, self.high))

    def to_optuna(self, trial):
        """Convert to optuna suggest_float with log if needed."""
        return trial.suggest_float(self.name, self.low, self.high, log=self.log_scale)

    def to_ray(self):
        """Convert to Ray Tune uniform distribution."""
        try:
            from ray import tune
            if self.log_scale:
                return tune.loguniform(self.low, self.high)
            return tune.uniform(self.low, self.high)
        except ImportError:
            return self


@dataclass
class Integer(ParameterDistribution):
    """Integer distribution."""
    low: int
    high: int
    log_scale: bool = False

    def sample(self, rng: Optional[np.random.RandomState] = None) -> int:
        """Sample integer from range."""
        if rng is None:
            rng = np.random.default_rng()

        if self.log_scale:
            log_low, log_high = np.log(self.low), np.log(self.high)
            return int(np.round(np.exp(rng.uniform(log_low, log_high))))
        return int(rng.integers(self.low, self.high + 1))

    def to_optuna(self, trial):
        """Convert to optuna suggest_int."""
        return trial.suggest_int(self.name, self.low, self.high, log=self.log_scale)

    def to_ray(self):
        """Convert to Ray Tune grid search."""
        try:
            from ray import tune
            return tune.randint(self.low, self.high + 1)
        except ImportError:
            return self


@dataclass
class Categorical(ParameterDistribution):
    """Categorical distribution."""
    choices: List[Any]
    probabilities: Optional[List[float]] = None

    def __post_init__(self):
        if self.probabilities is not None:
            assert len(self.probabilities) == len(self.choices)
            assert abs(sum(self.probabilities) - 1.0) < 1e-6

    def sample(self, rng: Optional[np.random.RandomState] = None) -> Any:
        """Sample from categorical distribution."""
        if rng is None:
            rng = np.random.default_rng()

        if self.probabilities:
            return rng.choice(self.choices, p=self.probabilities)
        return rng.choice(self.choices)

    def to_optuna(self, trial):
        """Convert to optuna suggest_categorical."""
        return trial.suggest_categorical(self.name, self.choices)

    def to_ray(self):
        """Convert to Ray Tune choice."""
        try:
            from ray import tune
            return tune.choice(self.choices)
        except ImportError:
            return self


@dataclass
class LogUniform(ParameterDistribution):
    """Log-uniform distribution."""
    low: float
    high: float

    def sample(self, rng: Optional[np.random.RandomState] = None) -> float:
        """Sample from log-uniform distribution."""
        if rng is None:
            rng = np.random.default_rng()
        log_low, log_high = np.log(self.low), np.log(self.high)
        return float(np.exp(rng.uniform(log_low, log_high)))

    def to_optuna(self, trial):
        """Convert to optuna suggest_float with log."""
        return trial.suggest_float(self.name, self.low, self.high, log=True)

    def to_ray(self):
        """Convert to Ray Tune loguniform."""
        try:
            from ray import tune
            return tune.loguniform(self.low, self.high)
        except ImportError:
            return self


class Float(Uniform):
    """Alias for Uniform distribution for clarity."""
    pass


@dataclass
class SearchSpace:
    """Complete search space for hyperparameter optimization."""

    parameters: Dict[str, ParameterDistribution] = field(default_factory=dict)
    constraints: List[Callable] = field(default_factory=list)

    def add(self, name: str, distribution: ParameterDistribution) -> 'SearchSpace':
        """Add a parameter to the search space."""
        self.parameters[name] = distribution
        distribution.name = name
        return self

    def add_continuous(
        self,
        name: str,
        low: float,
        high: float,
        log_scale: bool = False
    ) -> 'SearchSpace':
        """Add continuous parameter."""
        return self.add(name, Uniform(low, high, log_scale))

    def add_integer(
        self,
        name: str,
        low: int,
        high: int,
        log_scale: bool = False
    ) -> 'SearchSpace':
        """Add integer parameter."""
        return self.add(name, Integer(low, high, log_scale))

    def add_categorical(
        self,
        name: str,
        choices: List[Any],
        probabilities: Optional[List[float]] = None
    ) -> 'SearchSpace':
        """Add categorical parameter."""
        return self.add(name, Categorical(choices, probabilities))

    def sample(self, rng: Optional[np.random.RandomState] = None) -> Dict[str, Any]:
        """Sample a complete set of parameters."""
        return {
            name: dist.sample(rng)
            for name, dist in self.parameters.items()
        }

    def to_optuna(self, trial) -> Dict[str, Any]:
        """Convert to Optuna parameters."""
        return {
            name: dist.to_optuna(trial)
            for name, dist in self.parameters.items()
        }

    def validate(self, params: Dict[str, Any]) -> bool:
        """Validate that parameters satisfy constraints."""
        for constraint in self.constraints:
            if not constraint(params):
                return False
        return True

    def get_bounds(self) -> Dict[str, Tuple]:
        """Get bounds for all parameters."""
        bounds = {}
        for name, dist in self.parameters.items():
            if isinstance(dist, (Uniform, LogUniform)):
                bounds[name] = (dist.low, dist.high)
            elif isinstance(dist, Integer):
                bounds[name] = (dist.low, dist.high)
            elif isinstance(dist, Categorical):
                bounds[name] = tuple(str(c) for c in dist.choices)
        return bounds


# Convenience factory functions
def uniform(low: float, high: float) -> Uniform:
    """Create uniform distribution."""
    return Uniform("", low, high)


def loguniform(low: float, high: float) -> LogUniform:
    """Create log-uniform distribution."""
    return LogUniform("", low, high)


def int_range(low: int, high: int, log_scale: bool = False) -> Integer:
    """Create integer range distribution."""
    return Integer("", low, high, log_scale)


def choice(choices: List[Any], weights: Optional[List[float]] = None) -> Categorical:
    """Create categorical distribution."""
    return Categorical("", choices, weights)


class ConditionalSearchSpace(SearchSpace):
    """Search space with conditional parameters."""

    def __init__(self):
        super().__init__()
        self.conditional_params: Dict[str, List[Tuple[str, ParameterDistribution, Callable]]] = {}

    def add_conditional(
        self,
        condition: str,
        param_name: str,
        distribution: ParameterDistribution,
        condition_fn: Callable[[Dict], bool]
    ) -> 'ConditionalSearchSpace':
        """Add conditional parameter that only appears when condition_fn is true."""
        if condition not in self.conditional_params:
            self.conditional_params[condition] = []
        self.conditional_params[condition].append((param_name, distribution, condition_fn))
        return self

    def sample(self, rng: Optional[np.random.RandomState] = None) -> Dict[str, Any]:
        """Sample with conditional parameters."""
        params = super().sample(rng)

        for condition, cond_params in self.conditional_params.items():
            for param_name, dist, condition_fn in cond_params:
                if condition_fn(params):
                    params[param_name] = dist.sample(rng)

        return params


class NestedSearchSpace(SearchSpace):
    """Search space for nested architectures (e.g., layer sizes for neural networks)."""

    def __init__(
        self,
        max_depth: int = 5,
        size_range: Tuple[int, int] = (16, 512),
        dropout_range: Tuple[float, float] = (0.0, 0.5)
    ):
        super().__init__()
        self.max_depth = max_depth
        self.size_range = size_range
        self.dropout_range = dropout_range

    def sample(self, rng: Optional[np.random.RandomState] = None) -> Dict[str, Any]:
        """Sample nested architecture."""
        if rng is None:
            rng = np.random.default_rng()

        num_layers = rng.integers(1, self.max_depth + 1)
        architecture = []

        for i in range(num_layers):
            layer = {
                "units": int(rng.integers(self.size_range[0], self.size_range[1] + 1)),
                "dropout": float(rng.uniform(self.dropout_range[0], self.dropout_range[1])),
                "activation": str(rng.choice(["relu", "tanh", "gelu", "swish"])),
            }
            architecture.append(layer)

        return {
            "num_layers": num_layers,
            "architecture": architecture,
        }
